                for r in range(r0, r1) for c in range(c0, c1)
                if g[r][c] not in (0, sep)}

    def mirror(src, dst, flip_y=False, flip_x=False):
        sr0, sr1, sc0, sc1 = src
        dr0, dr1, dc0, dc1 = dst
        for (r, c), color in points(src).items():
            rr = dr0 + ((sr1-sr0-1-r) if flip_y else r)
            cc = dc0 + ((sc1-sc0-1-c) if flip_x else c)
            if rr < dr1 and cc < dc1:
                g[rr][cc] = color

    # Complete the paired motifs in each tile row.
    for row in tiles:
        for j in range(0, len(row)-1, 2):
            a, b = row[j], row[j+1]
            if points(a) and not points(b):
                mirror(a, b, flip_x=True)
            elif points(b) and not points(a):
                mirror(b, a, flip_x=True)

